sys_ui_action.script:
function triggerRcaGeneration() {
    g_form.addInfoMessage("Generating Root Cause Analysis via Now Assist... please wait.");

    var ga = new GlideAjax('sn_itsm_gen_ai.synergizeDemoUtils');
    ga.addParam('sysparm_name', 'getExecutionSkill');
    ga.addParam('sysparm_inc_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(response) {
        g_form.clearMessages(); 

        if (!response) {
            g_form.addErrorMessage("No response received from the server.");
            return;
        }

        var result = JSON.parse(response);
        if (result.error) {
            g_form.addErrorMessage(result.error);
            return;
        }

        var rawText = result.model_output;
        var formattedHtml = rawText.replace(/\n/g, '<br/>');

        // Escaping line breaks and single quotes for safe string parsing within the inline HTML onclick template literal
        var cleanTextForOnclick = rawText.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n').replace(/\r/g, '\\r');

        var modal = new GlideModal('glide_confirm_standard', false, 650);

        // Set standard plain text first to avoid the string escape bug
        modal.setTitle('Now Assist RCA Output');

        var htmlContent = '' +
            '<div style="padding:15px; font-family: Arial, sans-serif; font-size:13px; line-height:1.6; max-height:350px; overflow-y:auto; background:#fdfdfd; border:1px solid #e3e3e3; border-radius:4px; color:#333;">' + 
                formattedHtml + 
            '</div>' +
            '<div style="margin-top: 15px; text-align: right;">' +
                /* Copy Button: Copies to clipboard, locates the native UI page close element, and triggers it */
                '<button class="btn btn-default" style="margin-right: 10px;" onclick="(function(){ ' +
                    'copyToClipboard(\'' + cleanTextForOnclick + '\'); ' +
                    'var sysCloseBtn = document.getElementById(\'glide_confirm_standard_closemodal\'); ' +
                    'if(sysCloseBtn){ sysCloseBtn.click(); } ' +
                '})()">Copy to Clipboard</button>' +

                /* Post Button: Sets the field value, locates the native UI page close element, and triggers it */
                '<button class="btn btn-primary" style="background-color: #51cb87; border-color: #51cb87;" onclick="(function(){ ' +
                    'g_form.setValue(\'work_notes\', \'' + cleanTextForOnclick + '\'); ' +
                    'var sysCloseBtn = document.getElementById(\'glide_confirm_standard_closemodal\'); ' +
                    'if(sysCloseBtn){ sysCloseBtn.click(); } ' +
                    'g_form.addInfoMessage(\'RCA output added to Work notes field. Remember to Save/Update the Incident record to commit changes.\'); ' +
                '})()">Post as Worknotes</button>' +
            '</div>';

        modal.setBody(htmlContent, false, false);

        // STYLING FIX: Target both the header and title background with strict overrides
        setTimeout(function() {
            var modalHeaders = document.querySelectorAll('.modal-header, .modal-content .modal-header');
            var modalTitle = document.querySelector('.modal-title');
            var modalCloseBtn = document.getElementById('glide_confirm_standard_closemodal');

            // 1. Force the horizontal linear gradient across all variations of the title background container
            if (modalHeaders && modalHeaders.length > 0) {
                for (var i = 0; i < modalHeaders.length; i++) {
                    modalHeaders[i].style.setProperty('background', 'linear-gradient(90deg, #5de49b 0%, #3ca8a1 100%)', 'important');
                    modalHeaders[i].style.setProperty('border-bottom', 'none', 'important');
                }
            }

            // 2. Safely render the SVG sparkle icon inline with the title text
            if (modalTitle) {
                var sparkleIconSvg = '<svg viewBox="0 0 24 24" fill="currentColor" style="width:18px; height:18px; vertical-align:middle; margin-right:8px; display:inline-block;"><path d="M9 2L10.5 6.5L15 8L10.5 9.5L9 14L7.5 9.5L3 8L7.5 6.5L9 2Z"/><path d="M17 12L18 15L21 16L18 17L17 20L16 17L13 16L16 15L17 12Z"/></svg>';
                modalTitle.innerHTML = sparkleIconSvg + '<span>Now Assist RCA Output</span>';
                modalTitle.style.setProperty('color', '#ffffff', 'important');
                modalTitle.style.setProperty('font-weight', 'bold', 'important');
            }

            // 3. Make the close button white to blend beautifully with the title bar
            if (modalCloseBtn) {
                modalCloseBtn.style.setProperty('color', '#ffffff', 'important');
                modalCloseBtn.style.setProperty('opacity', '1', 'important');
                modalCloseBtn.style.setProperty('text-shadow', 'none', 'important');
            }
        }, 150); 
    });
}
